"""Exact dyadic interval intersections, with honest outward Arb envelopes."""
from fractions import Fraction as F


def unpack(encoded):
    if encoded is None:return 0,0,0,0
    return int(encoded[0][0],16),int(encoded[0][1]),int(encoded[1][0],16),int(encoded[1][1])


def pack(raw):
    m,e,r,re=raw
    if r<0:raise ValueError('Negative radius')
    return None if m==r==0 else [[hex(m),e],[hex(r),re]]


def endpoints(raw):
    m,e,r,re=raw
    if r<0:raise ValueError('Negative radius')
    common=min(e,re)
    midpoint=m<<(e-common);radius=r<<(re-common)
    return midpoint-radius,midpoint+radius,common


def align(interval,exponent):
    lo,hi,e=interval
    return lo<<(e-exponent),hi<<(e-exponent)


def contains_interval(outer,inner):
    e=min(outer[2],inner[2]);a,b=align(outer,e);c,d=align(inner,e)
    return a<=c and d<=b


def same_interval(a,b):
    return contains_interval(a,b) and contains_interval(b,a)


def dyadic_fraction(pair):
    m,e=pair;return F(m)*F(2)**e


def greater(a,b):
    e=min(a[1],b[1]);return (a[0]<<(a[1]-e))>(b[0]<<(b[1]-e))


def normalize(pair):
    m,e=pair
    if not m:return 0,0
    shift=(abs(m)&-abs(m)).bit_length()-1
    return m>>shift,e+shift


def dyadic_record(pair):
    m,e=normalize(pair);return [hex(m),e]


def as_arb(raw):
    from flint import arb
    m,e,r,re=raw
    return arb((m,e),(r,re))


def from_arb(value):
    if not value.is_finite():raise ArithmeticError('Nonfinite envelope')
    m,e=value.mid().man_exp();r,re=value.rad().man_exp()
    return int(m),int(e),int(r),int(re)


def intersect(taylor,universal):
    """Return a valid envelope, exact endpoints, and representation metadata.

    Nested inputs are copied exactly. For crossing inputs the exact endpoints
    remain primary; a rounded-radius envelope is never mistaken for an inner
    interval or shrunk to fit both parents.
    """
    from flint import ctx
    A,B=endpoints(taylor),endpoints(universal);e=min(A[2],B[2])
    a,b=align(A,e);c,d=align(B,e);exact=max(a,c),min(b,d),e
    if exact[0]>exact[1]:raise ArithmeticError('Disjoint authenticated source intervals')
    if a==c and b==d:
        selected=universal;relation='equal_intervals';mode='exact_universal_copy'
    elif a<=c and d<=b:
        selected=universal;relation='Taylor_contains_universal';mode='exact_universal_copy'
    elif c<=a and b<=d:
        selected=taylor;relation='universal_contains_Taylor';mode='exact_Taylor_copy'
    else:
        relation='overlapping_neither_contains'
        lo,hi,e=exact;mid=normalize((lo+hi,e-1));radius=normalize((hi-lo,e-1))
        if abs(mid[0]).bit_length()>ctx.prec:
            raise ArithmeticError('Fixed envelope precision cannot represent the exact midpoint')
        central=from_arb(as_arb((*mid,*radius)))
        rm,re=central[2:];common=min(e,re);rv=rm<<(re-common)
        left_mid=normalize(((lo<<(e-common))+rv,common))
        right_mid=normalize(((hi<<(e-common))-rv,common))
        candidates=[('centered_outward_Arb',central),
            ('left_endpoint_anchored_outward_Arb',from_arb(as_arb((*left_mid,rm,re)))),
            ('right_endpoint_anchored_outward_Arb',from_arb(as_arb((*right_mid,rm,re)))),
            ('Taylor_parent_envelope',taylor),('universal_parent_envelope',universal)]
        eligible=[]
        for order,(name,value) in enumerate(candidates):
            interval=endpoints(value)
            if not contains_interval(interval,exact):continue
            width=dyadic_fraction((interval[1]-interval[0],interval[2]))
            inside=int(contains_interval(A,interval))+int(contains_interval(B,interval))
            eligible.append((width,-inside,order,name,value))
        if not eligible:raise ArithmeticError('No outward envelope could be constructed')
        _,_,_,mode,selected=min(eligible,key=lambda v:v[:3])
    envelope=endpoints(selected)
    if not contains_interval(envelope,exact):raise ArithmeticError('Envelope loses an intersection endpoint')
    exact_copy=same_interval(envelope,exact)
    if relation!='overlapping_neither_contains' and not exact_copy:
        raise ArithmeticError('Nested intersection was not copied exactly')
    return selected,exact,dict(relation=relation,mode=mode,envelope_equals_exact_intersection=exact_copy,
        contained_in_Taylor=contains_interval(A,envelope),contained_in_universal=contains_interval(B,envelope))
